ATM_SFX_TRACK(sfxWin, ATM_VOL(44), ATM_SL_VOL((uint8_t)-3), ATM_NOTE_D5, ATM_DELAY(2), ATM_NOTE_F5_, ATM_DELAY(2), ATM_NOTE_A5, ATM_DELAY(2), ATM_NOTE_D6, ATM_DELAY(8)); // round won: bright rising, 13 bytes (ch1)
ATM_SFX_TRACK(sfxLose, ATM_VOL(44), ATM_SL_VOL((uint8_t)-3), ATM_NOTE_A5, ATM_DELAY(2), ATM_NOTE_F5, ATM_DELAY(2), ATM_NOTE_D5, ATM_DELAY(2), ATM_NOTE_A4, ATM_DELAY(8)); // round lost: falling, 13 bytes (ch1)
ATM_SFX_TRACK(sfxTick, ATM_VOL(36), ATM_SL_VOL((uint8_t)-8), ATM_NOTE_G4, ATM_DELAY(1), ATM_NOTE_D5, ATM_DELAY(2)); // pass the Arduboy: tick, 9 bytes (ch1)
ATM_SFX_TRACK(sfxBoost, ATM_VOL(36), ATM_SL_VOL((uint8_t)-3), ATM_NOTE_E6, ATM_DELAY(1), ATM_NOTE_B5, ATM_DELAY(1), ATM_NOTE_E6, ATM_DELAY(1), ATM_NOTE_B6, ATM_DELAY(4)); // element boost: shimmer, 13 bytes (ch1)
